// AxISA v2.2 step 2 (see sw/metro_test.axasm and docs/ISA.md's METRO
// section): bit-exact Boltzmann weights, accept rates, cycle counts.
// GENERATED by tools/gen_metro_test.py.
`timescale 1ns/1ps
`ifndef INSTR_HEX
`define INSTR_HEX "sw/metro_test.hex"
`endif

module tb_metro;
    reg clk, reset;
    integer errors;
    integer max_cycles;
    integer cycle_count;

    wire halted;
    wire [31:0] tohost_value;
    wire        bus_req, bus_mem_write, bus_mem_unsigned, bus_grant;
    wire [31:0] bus_addr, bus_write_data, bus_read_data;
    wire [1:0]  bus_mem_size;
    wire        uart_tx_valid;
    wire [7:0]  uart_tx_data;

    cpu_core #(.INSTR_MEM_WORDS(1024), .INSTR_INIT_FILE(`INSTR_HEX)) dut (
        .clk(clk), .reset(reset), .halted(halted), .tohost_value(tohost_value),
        .irq_in(1'b0),
        .bus_req(bus_req), .bus_addr(bus_addr), .bus_write_data(bus_write_data),
        .bus_mem_write(bus_mem_write), .bus_mem_size(bus_mem_size), .bus_mem_unsigned(bus_mem_unsigned),
        .bus_grant(1'b0), .bus_read_data(32'b0),
        .uart_tx_valid(uart_tx_valid), .uart_tx_data(uart_tx_data),
        .uart_rx_data_in(8'b0), .uart_rx_ready_in(1'b0), .uart_rx_ack()
    );

    always #5 clk = ~clk;

    // cycles each METRO keeps is_metro high, by kind
    integer lat [0:8191];
    integer n_lat, cur;
    initial begin n_lat = 0; cur = 0; end
    always @(posedge clk) begin
        if (!reset && dut.is_metro) cur = cur + 1;
        else if (cur != 0) begin
            if (n_lat < 8192) lat[n_lat] = cur;
            n_lat = n_lat + 1;
            cur = 0;
        end
    end


    // The w = 0 loop runs with the LFSR forced to 0, so r = +0 exactly:
    // r < w must still say no. From rate 0's stored count until rate 2's
    // P_old (ln 4) is loaded.
    initial begin
        wait (dut.dmem.mem[256] == 2000);
        force dut.lfsr_q = 32'h0;
        wait (dut.n_bank.regs[1] === 32'h3FB17218);
        release dut.lfsr_q;
    end

    task check(input [31:0] got, input [31:0] expected, input [48*8-1:0] name);
        begin
            if (got !== expected) begin
                $display("FAIL: %0s got=%0d (0x%h) expected=%0d (0x%h)", name, got, got, expected, expected);
                errors = errors + 1;
            end else begin
                $display("PASS: %0s = %0d (0x%h)", name, got, got);
            end
        end
    endtask

    task in_range(input [31:0] got, input [31:0] lo, input [31:0] hi, input [48*8-1:0] name);
        begin
            if (got < lo || got > hi) begin
                $display("FAIL: %0s got=%0d expected %0d..%0d", name, got, lo, hi);
                errors = errors + 1;
            end else
                $display("PASS: %0s = %0d (allowed %0d..%0d)", name, got, lo, hi);
        end
    endtask

    initial begin
        errors = 0;
        max_cycles = 200000;

        clk = 0;
        reset = 1;
        cycle_count = 0;
        @(posedge clk); @(posedge clk);
        reset = 0;

        while (!halted && cycle_count < max_cycles) begin
            @(posedge clk);
            cycle_count = cycle_count + 1;
        end

        if (!halted) begin
            $display("FAIL: core never halted within %0d cycles", max_cycles);
            errors = errors + 1;
        end else begin
            $display("Halted after %0d cycles. tohost=%0d", cycle_count, tohost_value);
            check(tohost_value, 32'd0, "tohost");
            check(dut.dmem.mem[192], 32'h3F800000, "w #0 (1)");
            check(dut.dmem.mem[193], 32'h3F800000, "w #1 (1)");
            check(dut.dmem.mem[194], 32'h3F800000, "w #2 (1)");
            check(dut.dmem.mem[195], 32'h3F7FFC16, "w #3 (0.99994)");
            check(dut.dmem.mem[196], 32'h3F000000, "w #4 (0.5)");
            check(dut.dmem.mem[197], 32'h3EBC5AB2, "w #5 (0.367879)");
            check(dut.dmem.mem[198], 32'h3D1712D0, "w #6 (0.0368832)");
            check(dut.dmem.mem[199], 32'h3B85EA54, "w #7 (0.00408677)");
            check(dut.dmem.mem[200], 32'h310DA432, "w #8 (2.06115e-09)");
            check(dut.dmem.mem[201], 32'h00B336A1, "w #9 (1.64582e-38)");
            check(dut.dmem.mem[202], 32'h00000000, "w #10 (0)");
            check(dut.dmem.mem[203], 32'h00000000, "w #11 (0)");
            check(dut.dmem.mem[204], 32'h3F800000, "w #12 (1)");
            check(dut.dmem.mem[205], 32'h3F800000, "w #13 (1)");
            check(dut.dmem.mem[206], 32'h3DAEFCAC, "w #14 (0.0854429)");
            check(dut.dmem.mem[207], 32'h3DF5CF84, "w #15 (0.120025)");
            check(dut.dmem.mem[208], 32'h3F0A2465, "w #16 (0.539618)");
            check(dut.dmem.mem[209], 32'h3F800000, "w #17 (1)");
            check(dut.dmem.mem[210], 32'h3D167A00, "w #18 (0.0367374)");
            check(dut.dmem.mem[211], 32'h3C945906, "w #19 (0.0181089)");
            check(dut.dmem.mem[212], 32'h3F800000, "w #20 (1)");
            check(dut.dmem.mem[213], 32'h3F800000, "w #21 (1)");
            check(dut.dmem.mem[214], 32'h3F800000, "w #22 (1)");
            check(dut.dmem.mem[215], 32'h3DBC0A8A, "w #23 (0.091817)");
            check(dut.dmem.mem[216], 32'h3F800000, "w #24 (1)");
            check(dut.dmem.mem[217], 32'h3F800000, "w #25 (1)");
            check(dut.dmem.mem[218], 32'h3F800000, "w #26 (1)");
            check(dut.dmem.mem[219], 32'h3F1A8810, "w #27 (0.603639)");
            check(dut.dmem.mem[220], 32'h3F800000, "w #28 (1)");
            check(dut.dmem.mem[221], 32'h30014094, "w #29 (4.70217e-10)");
            check(dut.dmem.mem[222], 32'h3F800000, "w #30 (1)");
            check(dut.dmem.mem[223], 32'h3F800000, "w #31 (1)");
            check(dut.dmem.mem[224], 32'h3F5DD32E, "w #32 (0.866504)");
            check(dut.dmem.mem[225], 32'h3F046957, "w #33 (0.517232)");
            check(dut.dmem.mem[226], 32'h3EADF07E, "w #34 (0.339725)");
            check(dut.dmem.mem[227], 32'h3F2F1B75, "w #35 (0.684013)");
            in_range(dut.dmem.mem[256], 1999, 2000, "accepts of 2000, w = 1.0000");
            in_range(dut.dmem.mem[257], 0, 0, "accepts of 2000, w = 0.0000");
            in_range(dut.dmem.mem[258], 412, 588, "accepts of 2000, w = 0.2500");
            in_range(dut.dmem.mem[259], 1412, 1588, "accepts of 2000, w = 0.7500");
            check(n_lat, 8036, "METRO instructions seen");
            check(lat[0], 6, "cycles of WEIGHT #0");
            check(lat[1], 6, "cycles of WEIGHT #1");
            check(lat[2], 6, "cycles of WEIGHT #2");
            check(lat[3], 27, "cycles of WEIGHT #3");
            check(lat[4], 27, "cycles of WEIGHT #4");
            check(lat[5], 27, "cycles of WEIGHT #5");
            check(lat[6], 27, "cycles of WEIGHT #6");
            check(lat[7], 27, "cycles of WEIGHT #7");
            check(lat[8], 27, "cycles of WEIGHT #8");
            check(lat[9], 27, "cycles of WEIGHT #9");
            check(lat[10], 27, "cycles of WEIGHT #10");
            check(lat[11], 8, "cycles of WEIGHT #11");
            check(lat[12], 6, "cycles of WEIGHT #12");
            check(lat[13], 6, "cycles of WEIGHT #13");
            check(lat[14], 27, "cycles of WEIGHT #14");
            check(lat[15], 27, "cycles of WEIGHT #15");
            check(lat[16], 27, "cycles of WEIGHT #16");
            check(lat[17], 6, "cycles of WEIGHT #17");
            check(lat[18], 27, "cycles of WEIGHT #18");
            check(lat[19], 27, "cycles of WEIGHT #19");
            check(lat[20], 6, "cycles of WEIGHT #20");
            check(lat[21], 6, "cycles of WEIGHT #21");
            check(lat[22], 6, "cycles of WEIGHT #22");
            check(lat[23], 27, "cycles of WEIGHT #23");
            check(lat[24], 6, "cycles of WEIGHT #24");
            check(lat[25], 6, "cycles of WEIGHT #25");
            check(lat[26], 6, "cycles of WEIGHT #26");
            check(lat[27], 27, "cycles of WEIGHT #27");
            check(lat[28], 6, "cycles of WEIGHT #28");
            check(lat[29], 27, "cycles of WEIGHT #29");
            check(lat[30], 6, "cycles of WEIGHT #30");
            check(lat[31], 6, "cycles of WEIGHT #31");
            check(lat[32], 27, "cycles of WEIGHT #32");
            check(lat[33], 27, "cycles of WEIGHT #33");
            check(lat[34], 27, "cycles of WEIGHT #34");
            check(lat[35], 27, "cycles of WEIGHT #35");
            check(lat[36], 8, "cycles of ACCEPT, dS <= 0");
            check(lat[2036], 10, "cycles of ACCEPT, w = 0");
            check(lat[4036], 29, "cycles of ACCEPT, full path");
        end

        if (errors == 0) $display("ALL AXISA METRO TESTS PASSED");
        else $display("%0d AXISA METRO TEST(S) FAILED", errors);
        $finish;
    end
endmodule
